        .nth(1)
        .unwrap();
    let hello = project.write("hello.typ", "Hi");
    exec().arg("compile").arg(&hello).must_succeed();
    project
        .read("hello.pdf")
        .must_contain(format!("/Creator(Typst {version})").as_bytes());
}

